            ':name' => $validation['data']['name'],
            ':email' => $validation['data']['email'],
            ':message' => $validation['data']['message']
        ]);

        echo "Thank you! Your message has been received.";
    } else {
        echo "Errors: " . implode(", ", $validation['errors']);
    }
}
?>
```

