"""
A simple HTTP server for serving static files.
Usage: python simple_static_server.py [port] [directory]
Default port: 8000
Default directory: current directory
"""

import http.server
import socketserver
import os
import sys
from pathlib import Path


class StaticFileHandler(http.server.SimpleHTTPRequestHandler):
    """Custom handler for serving static files with better logging"""

    def log_message(self, format, *args):
        """Override to provide cleaner log messages"""
        print(f"[{self.log_date_time_string()}] {format % args}")

    def end_headers(self):
        """Add custom headers for better static file serving"""
        # Add cache control headers
        self.send_header('Cache-Control', 'public, max-age=3600')
        super().end_headers()


def run_server(port=8000, directory=None):
    """
    Start the static file server

    Args:
        port (int): Port number to run the server on
        directory (str): Directory to serve files from
    """
    # Set the directory to serve files from
    if directory:
        os.chdir(directory)
        print(f"Serving files from: {os.getcwd()}")
    else:
        print(f"Serving files from: {os.getcwd()}")

    # Create the server
    with socketserver.TCPServer(("", port), StaticFileHandler) as httpd:
        print(f"Server running at http://localhost:{port}/")
        print("Press Ctrl+C to stop the server")

        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            print("\nServer stopped.")
            sys.exit(0)


def main():
    """Main entry point"""
    port = 8000
    directory = None

    # Parse command line arguments
    if len(sys.argv) > 1:
        try:
            port = int(sys.argv[1])
        except ValueError:
            print(f"Invalid port number: {sys.argv[1]}")
            sys.exit(1)

    if len(sys.argv) > 2:
        directory = sys.argv[2]
        if not os.path.isdir(directory):
            print(f"Directory not found: {directory}")
            sys.exit(1)

    run_server(port, directory)


if __name__ == "__main__":
    main()
