I'll provide you with a comprehensive JavaScript snippet for tracking user interactions on a website. This solution includes tracking various types of user interactions like clicks, form submissions, page views, and scroll depth.

```javascript
// User Interaction Tracking System
(function() {
    'use strict';

    // Configuration
    const config = {
        trackClicks: true,
        trackFormSubmissions: true,
        trackPageViews: true,
        trackScrollDepth: true,
        trackTimeOnPage: true,
        apiEndpoint: '/api/track', // Your tracking endpoint
        debug: true // Set to false in production
    };

    // Utility function to send tracking data
    function sendTrackingData(eventType, eventData) {
        const trackingPayload = {
            eventType: eventType,
            eventData: eventData,
            timestamp: new Date().toISOString(),
            url: window.location.href,
            userAgent: navigator.userAgent,
            sessionId: getSessionId()
        };

        if (config.debug) {
            console.log('Tracking Event:', trackingPayload);
        }

        // Send data to your analytics endpoint
        if (navigator.sendBeacon) {
            // Use sendBeacon for better reliability
            navigator.sendBeacon(
                config.apiEndpoint,
                JSON.stringify(trackingPayload)
            );
        } else {
            // Fallback to fetch
            fetch(config.apiEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(trackingPayload),
                keepalive: true
            }).catch(err => console.error('Tracking error:', err));
        }
    }

    // Generate or retrieve session ID
    function getSessionId() {
        let sessionId = sessionStorage.getItem('tracking_session_id');
        if (!sessionId) {
            sessionId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            sessionStorage.setItem('tracking_session_id', sessionId);
        }
        return sessionId;
    }

    // Track page views
    function trackPageView() {
        if (!config.trackPageViews) return;

        sendTrackingData('pageview', {
            title: document.title,
            referrer: document.referrer,
            path: window.location.pathname
        });
    }

    // Track clicks
    function trackClicks() {
        if (!config.trackClicks) return;

        document.addEventListener('click', function(e) {
            const target = e.target;
            const tagName = target.tagName.toLowerCase();

            const clickData = {
                element: tagName,
                text: target.textContent.trim().substring(0, 100),
                id: target.id || null,
                classes: target.className || null,
                href: target.href || null
            };

            sendTrackingData('click', clickData);
        }, true);
    }

    // Track form submissions
    function trackFormSubmissions() {
        if (!config.trackFormSubmissions) return;

        document.addEventListener('submit', function(e) {
            const form = e.target;

            const formData = {
                formId: form.id || null,
                formName: form.name || null,
                formAction: form.action || null,
                formMethod: form.method || null,
                fieldCount: form.elements.length
            };

            sendTrackingData('form_submission', formData);
        }, true);
    }

    // Track scroll depth
    function trackScrollDepth() {
        if (!config.trackScrollDepth) return;

        let maxScroll = 0;
        const scrollMilestones = [25, 50, 75, 100];
        const reachedMilestones = new Set();

        window.addEventListener('scroll', debounce(function() {
            const scrollPercentage = Math.round(
                (window.scrollY + window.innerHeight) / document.documentElement.scrollHeight * 100
            );

            if (scrollPercentage > maxScroll) {
                maxScroll = scrollPercentage;
            }

            scrollMilestones.forEach(milestone => {
                if (scrollPercentage >= milestone && !reachedMilestones.has(milestone)) {
                    reachedMilestones.add(milestone);
                    sendTrackingData('scroll_depth', {
                        milestone: milestone,
                        maxScroll: maxScroll
                    });
                }
            });
        }, 500));
    }

    // Track time on page
    function trackTimeOnPage() {
        if (!config.trackTimeOnPage) return;

        const startTime = Date.now();
        let isActive = true;
        let totalActiveTime = 0;
        let lastActiveTime = startTime;

        // Track if user is active
        ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart'].forEach(event => {
            document.addEventListener(event, function() {
                if (!isActive) {
                    lastActiveTime = Date.now();
                    isActive = true;
                }
            }, true);
        });

        // Track when user becomes inactive
        let inactivityTimer;
        function resetInactivityTimer() {
            clearTimeout(inactivityTimer);
            inactivityTimer = setTimeout(() => {
                if (isActive) {
                    totalActiveTime += Date.now() - lastActiveTime;
                    isActive = false;
                }
            }, 30000); // 30 seconds of inactivity
        }

        document.addEventListener('mousemove', resetInactivityTimer);
        document.addEventListener('keypress', resetInactivityTimer);

        // Send time on page when user leaves
        window.addEventListener('beforeunload', function() {
            if (isActive) {
                totalActiveTime += Date.now() - lastActiveTime;
            }

            sendTrackingData('time_on_page', {
                totalTime: Math.round((Date.now() - startTime) / 1000),
                activeTime: Math.round(totalActiveTime / 1000)
            });
        });
    }

    // Debounce utility function
    function debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
            const later = () => {
                clearTimeout(timeout);
                func(...args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
        };
    }

    // Initialize tracking
    function init() {
        trackPageView();
        trackClicks();
        trackFormSubmissions();
        trackScrollDepth();
        trackTimeOnPage();

        if (config.debug) {
            console.log('User interaction tracking initialized');
        }
    }

    // Start tracking when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

})();
```

**Key Features:**

1. **Click Tracking** - Captures all user clicks with element details
2. **Form Submission Tracking** - Monitors form submissions
3. **Page View Tracking** - Records page visits
4. **Scroll Depth Tracking** - Measures how far users scroll (25%, 50%, 75%, 100%)
5. **Time on Page** - Tracks both total and active time
6. **Session Management** - Maintains session IDs across page views
7. **Reliable Data Sending** - Uses `sendBeacon` API with fetch fallback

**Usage:**

1. Include this script in your website
2. Update `config.apiEndpoint` to your tracking server endpoint
3. Set `config.debug` to `false` in production
4. Customize which events to track by modifying the config object

