I'll help you create a basic user authentication system in JavaScript. Let me provide you with a simple implementation that includes user registration, login, and secure password storage.

```javascript
// Basic User Authentication System in JavaScript

// Using crypto for password hashing (Node.js built-in module)
const crypto = require('crypto');

class UserAuthSystem {
  constructor() {
    // In-memory storage (in production, use a database)
    this.users = new Map();
    this.tokens = new Map();
  }

  // Hash password using SHA-256
  hashPassword(password, salt) {
    const hash = crypto.createHmac('sha256', salt);
    hash.update(password);
    return hash.digest('hex');
  }

  // Generate a random salt
  generateSalt() {
    return crypto.randomBytes(16).toString('hex');
  }

  // Generate authentication token
  generateToken() {
    return crypto.randomBytes(32).toString('hex');
  }

  // Register a new user
  register(username, password, email) {
    // Check if user already exists
    if (this.users.has(username)) {
      return {
        success: false,
        message: 'Username already exists'
      };
    }

    // Validate input
    if (!username || !password || !email) {
      return {
        success: false,
        message: 'All fields are required'
      };
    }

    if (password.length < 8) {
      return {
        success: false,
        message: 'Password must be at least 8 characters long'
      };
    }

    // Generate salt and hash password
    const salt = this.generateSalt();
    const hashedPassword = this.hashPassword(password, salt);

    // Store user data
    this.users.set(username, {
      username,
      email,
      passwordHash: hashedPassword,
      salt,
      createdAt: new Date()
    });

    return {
      success: true,
      message: 'User registered successfully'
    };
  }

  // Login user
  login(username, password) {
    // Check if user exists
    if (!this.users.has(username)) {
      return {
        success: false,
        message: 'Invalid username or password'
      };
    }

    const user = this.users.get(username);

    // Hash the provided password with stored salt
    const hashedPassword = this.hashPassword(password, user.salt);

    // Compare hashed passwords
    if (hashedPassword !== user.passwordHash) {
      return {
        success: false,
        message: 'Invalid username or password'
      };
    }

    // Generate authentication token
    const token = this.generateToken();
    const tokenExpiry = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

    // Store token
    this.tokens.set(token, {
      username,
      expiresAt: tokenExpiry
    });

    return {
      success: true,
      message: 'Login successful',
      token,
      expiresAt: tokenExpiry
    };
  }

  // Verify authentication token
  verifyToken(token) {
    if (!this.tokens.has(token)) {
      return {
        success: false,
        message: 'Invalid token'
      };
    }

    const tokenData = this.tokens.get(token);

    // Check if token has expired
    if (new Date() > tokenData.expiresAt) {
      this.tokens.delete(token);
      return {
        success: false,
        message: 'Token has expired'
      };
    }

    return {
      success: true,
      username: tokenData.username
    };
  }

  // Logout user (invalidate token)
  logout(token) {
    if (this.tokens.has(token)) {
      this.tokens.delete(token);
      return {
        success: true,
        message: 'Logged out successfully'
      };
    }

    return {
      success: false,
      message: 'Invalid token'
    };
  }

  // Change password
  changePassword(username, oldPassword, newPassword) {
    if (!this.users.has(username)) {
      return {
        success: false,
        message: 'User not found'
      };
    }

    const user = this.users.get(username);
    const hashedOldPassword = this.hashPassword(oldPassword, user.salt);

    // Verify old password
    if (hashedOldPassword !== user.passwordHash) {
      return {
        success: false,
        message: 'Incorrect old password'
      };
    }

    // Validate new password
    if (newPassword.length < 8) {
      return {
        success: false,
        message: 'New password must be at least 8 characters long'
      };
    }

    // Generate new salt and hash new password
    const newSalt = this.generateSalt();
    const newHashedPassword = this.hashPassword(newPassword, newSalt);

    // Update user data
    user.salt = newSalt;
    user.passwordHash = newHashedPassword;
    this.users.set(username, user);

    return {
      success: true,
      message: 'Password changed successfully'
    };
  }
}

// Example usage
const authSystem = new UserAuthSystem();

// Register a user
console.log(authSystem.register('john_doe', 'SecurePass123', 'john@example.com'));

// Login
const loginResult = authSystem.login('john_doe', 'SecurePass123');
console.log(loginResult);

// Verify token
if (loginResult.success) {
  console.log(authSystem.verifyToken(loginResult.token));
}

// Logout
if (loginResult.success) {
  console.log(authSystem.logout(loginResult.token));
}

// Export for use in other modules
module.exports = UserAuthSystem;
```

## Key Features:

1. **Password Security:**
   - Passwords are hashed using SHA-256 with a unique salt for each user
   - Salts prevent rainbow table attacks
   - Original passwords are never stored

2. **Token-Based Authentication:**
   - Generates secure random tokens for authenticated sessions
   - Tokens expire after 24 hours
   - Tokens can be invalidated on logout

3. **User Management:**
   - User registration with validation
   - Login with credential verification
   - Password change functionality
   - Token verification for protected routes

4. **Security Best Practices:**
   - Minimum password length requirement (8 characters)
   - Unique salt per user
   - Token expiration
   - No plain-text password storage

## For Production Use:

Consider these improvements:
- Use bcrypt or argon2 instead of SHA-256 for password hashing
- Store data in a proper database (MongoDB, PostgreSQL, etc.)
- Implement rate limiting to prevent brute force attacks
- Add email verification
- Implement password reset functionality
- Use HTTPS for all communications
- Add CSRF protection
- Implement refresh tokens for better security

This implementation provides a solid foundation for a basic authentication system that you can expand based on your specific requirements!

